//! Contains codec interface and supported codec implementations.
//!
//! See [`Compression`](crate::basic::Compression) enum for all available compression
//! algorithms.
//!
#[cfg_attr(
    feature = "experimental",
    doc = r##"
# Example

```no_run
use parquet::{basic::Compression, compression::{create_codec, CodecOptionsBuilder}};

let codec_options = CodecOptionsBuilder::default()
    .set_backward_compatible_lz4(false)
    .build();
let mut codec = match create_codec(Compression::SNAPPY, &codec_options) {
 Ok(Some(codec)) => codec,
 _ => panic!(),
};

let data = vec![b'p', b'a', b'r', b'q', b'u', b'e', b't'];
let mut compressed = vec![];
codec.compress(&data[..], &mut compressed).unwrap();

let mut output = vec![];
codec.decompress(&compressed[..], &mut output, None).unwrap();

assert_eq!(output, data);
```
"##
)]
use crate::basic::Compression as CodecType;
use crate::errors::{ParquetError, Result};

/// Parquet compression codec interface.
pub trait Codec: Send {
    /// Compresses data stored in slice `input_buf` and appends the compressed result
    /// to `output_buf`.
    ///
    /// Note that you'll need to call `clear()` before reusing the same `output_buf`
    /// across different `compress` calls.
    fn compress(&mut self, input_buf: &[u8], output_buf: &mut Vec<u8>) -> Result<()>;

    /// Decompresses data stored in slice `input_buf` and appends output to `output_buf`.
    ///
    /// If the uncompress_size is provided it will allocate the exact amount of memory.
    /// Otherwise, it will estimate the uncompressed size, allocating an amount of memory
    /// greater or equal to the real uncompress_size.
    ///
    /// Returns the total number of bytes written.
    fn decompress(
        &mut self,
        input_buf: &[u8],
        output_buf: &mut Vec<u8>,
        uncompress_size: Option<usize>,
    ) -> Result<usize>;
}

/// Struct to hold `Codec` creation options.
#[derive(Debug, PartialEq, Eq)]
pub struct CodecOptions {
    /// Whether or not to fallback to other LZ4 older implementations on error in LZ4_HADOOP.
    backward_compatible_lz4: bool,
}

impl Default for CodecOptions {
    fn default() -> Self {
        CodecOptionsBuilder::default().build()
    }
}

pub struct CodecOptionsBuilder {
    /// Whether or not to fallback to other LZ4 older implementations on error in LZ4_HADOOP.
    backward_compatible_lz4: bool,
}

impl Default for CodecOptionsBuilder {
    fn default() -> Self {
        Self {
            backward_compatible_lz4: true,
        }
    }
}

impl CodecOptionsBuilder {
    /// Enable/disable backward compatible LZ4.
    ///
    /// If backward compatible LZ4 is enable, on LZ4_HADOOP error it will fallback
    /// to the older versions LZ4 algorithms. That is LZ4_FRAME, for backward compatibility
    /// with files generated by older versions of this library, and LZ4_RAW, for backward
    /// compatibility with files generated by older versions of parquet-cpp.
    ///
    /// If backward compatible LZ4 is disabled, on LZ4_HADOOP error it will return the error.
    pub fn set_backward_compatible_lz4(mut self, value: bool) -> CodecOptionsBuilder {
        self.backward_compatible_lz4 = value;
        self
    }

    pub fn build(self) -> CodecOptions {
        CodecOptions {
            backward_compatible_lz4: self.backward_compatible_lz4,
        }
    }
}

/// Defines valid compression levels.
pub(crate) trait CompressionLevel<T: std::fmt::Display + std::cmp::PartialOrd> {
    const MINIMUM_LEVEL: T;
    const MAXIMUM_LEVEL: T;

    /// Tests if the provided compression level is valid.
    fn is_valid_level(level: T) -> Result<()> {
        let compression_range = Self::MINIMUM_LEVEL..=Self::MAXIMUM_LEVEL;
        if compression_range.contains(&level) {
            Ok(())
        } else {
            Err(ParquetError::General(format!(
                "valid compression range {}..={} exceeded.",
                compression_range.start(),
                compression_range.end()
            )))
        }
    }
}

/// Given the compression type `codec`, returns a codec used to compress and decompress
/// bytes for the compression type.
/// This returns `None` if the codec type is `UNCOMPRESSED`.
pub fn create_codec(codec: CodecType, _options: &CodecOptions) -> Result<Option<Box<dyn Codec>>> {
    if let Some(policy) = crate::resource::current() {
        return create_admitted_codec(codec, policy);
    }
    #[allow(unreachable_code, unused_variables)]
    match codec {
        CodecType::BROTLI(level) => {
            #[cfg(any(feature = "brotli", test))]
            return Ok(Some(Box::new(BrotliCodec::new(level))));
            Err(ParquetError::General(
                "Disabled feature at compile time: brotli".into(),
            ))
        }
        CodecType::GZIP(level) => {
            #[cfg(any(feature = "flate2", test))]
            return Ok(Some(Box::new(GZipCodec::new(level))));
            Err(ParquetError::General(
                "Disabled feature at compile time: flate2".into(),
            ))
        }
        CodecType::SNAPPY => {
            #[cfg(any(feature = "snap", test))]
            return Ok(Some(Box::new(SnappyCodec::new())));
            Err(ParquetError::General(
                "Disabled feature at compile time: snap".into(),
            ))
        }
        CodecType::LZ4 => {
            #[cfg(any(feature = "lz4", test))]
            return Ok(Some(Box::new(LZ4HadoopCodec::new(
                _options.backward_compatible_lz4,
            ))));
            Err(ParquetError::General(
                "Disabled feature at compile time: lz4".into(),
            ))
        }
        CodecType::ZSTD(level) => {
            #[cfg(any(feature = "zstd", test))]
            return Ok(Some(Box::new(ZSTDCodec::new(level))));
            Err(ParquetError::General(
                "Disabled feature at compile time: zstd".into(),
            ))
        }
        CodecType::LZ4_RAW => {
            #[cfg(any(feature = "lz4", test))]
            return Ok(Some(Box::new(LZ4RawCodec::new())));
            Err(ParquetError::General(
                "Disabled feature at compile time: lz4".into(),
            ))
        }
        CodecType::UNCOMPRESSED => Ok(None),
        _ => Err(nyi_err!("The codec type {} is not supported yet", codec)),
    }
}

// The diagnostic itself must retain the original admission bank. Keeping the
// native error inline avoids allocating a String before admission.
#[derive(Debug)]
struct ScopedCodecError<E> {
    error: E,
    _policy: crate::resource::ReaderResourcePolicy,
}
impl<E: std::fmt::Display> std::fmt::Display for ScopedCodecError<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.error.fmt(f)
    }
}
impl<E: std::error::Error + 'static> std::error::Error for ScopedCodecError<E> {}

#[derive(Debug)]
struct CodecMessage(&'static str);
impl std::fmt::Display for CodecMessage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.0)
    }
}
impl std::error::Error for CodecMessage {}

fn admitted_codec_error<E: std::error::Error + Send + Sync + 'static>(
    policy: &crate::resource::ReaderResourcePolicy,
    error: E,
) -> ParquetError {
    match policy.reserve(
        std::mem::size_of::<ScopedCodecError<E>>(),
        "codec diagnostic",
    ) {
        Ok(()) => ParquetError::External(Box::new(ScopedCodecError {
            error,
            _policy: policy.clone(),
        })),
        Err(error) => error.into(),
    }
}

fn create_admitted_codec(
    codec: CodecType,
    policy: crate::resource::ReaderResourcePolicy,
) -> Result<Option<Box<dyn Codec>>> {
    match codec {
        CodecType::UNCOMPRESSED => Ok(None),
        #[cfg(any(feature = "zstd", test))]
        CodecType::ZSTD(level) => {
            policy.reserve(
                std::mem::size_of::<admitted_zstd::StaticCodec>(),
                "zstd codec owner",
            )?;
            Ok(Some(Box::new(admitted_zstd::StaticCodec::new(
                level, policy,
            ))))
        }
        #[cfg(any(feature = "snap", test))]
        CodecType::SNAPPY => {
            policy.reserve(
                std::mem::size_of::<AdmittedSnappyCodec>(),
                "snappy codec owner",
            )?;
            Ok(Some(Box::new(AdmittedSnappyCodec {
                encoder: snap::raw::Encoder::new(),
                scratch_admitted: false,
                decoder: AdmittedSnappyDecoder { policy },
            })))
        }
        _ => Err(crate::resource::ResourceExhausted {
            kind: "unsupported bounded codec profile",
            requested: 1,
            limit: 0,
        }
        .into()),
    }
}

#[cfg(any(feature = "snap", test))]
struct AdmittedSnappyCodec {
    encoder: snap::raw::Encoder,
    scratch_admitted: bool,
    decoder: AdmittedSnappyDecoder,
}
#[cfg(any(feature = "snap", test))]
impl Codec for AdmittedSnappyCodec {
    fn compress(&mut self, input: &[u8], output: &mut Vec<u8>) -> Result<()> {
        let policy = &self.decoder.policy;
        crate::resource::validate_thread_owner(Some(policy))?;
        let _scope = crate::resource::enter(Some(policy.clone()));
        crate::resource::ReaderResourcePolicy::check(
            input.len(),
            policy.limits().page_bytes,
            "snappy input bytes",
        )?;
        if !self.scratch_admitted {
            // snap 1.1.1 Encoder::block_table allocates its only heap scratch
            // once: MAX_TABLE_SIZE (1 << 14) u16 entries. Its small table is
            // inline in the already admitted codec Box.
            let bytes = (1usize << 14) * std::mem::size_of::<u16>();
            crate::resource::ReaderResourcePolicy::check(
                bytes,
                policy.limits().codec_bytes,
                "snappy encoder scratch",
            )?;
            policy.reserve(bytes, "snappy encoder scratch")?;
            self.scratch_admitted = true;
        }
        let bound = snap::raw::max_compress_len(input.len());
        if bound == 0 {
            return Err(crate::resource::ResourceExhausted {
                kind: "snappy input bytes",
                requested: input.len(),
                limit: u32::MAX as usize,
            }
            .into());
        }
        let start = output.len();
        crate::resource::reserve_vec(output, bound, "snappy encoded output")?;
        output.resize(start + bound, 0);
        match self.encoder.compress(input, &mut output[start..]) {
            Ok(written) => {
                output.truncate(start + written);
                Ok(())
            }
            Err(error) => {
                output.truncate(start);
                Err(admitted_codec_error(policy, error))
            }
        }
    }
    fn decompress(
        &mut self,
        input: &[u8],
        output: &mut Vec<u8>,
        expected: Option<usize>,
    ) -> Result<usize> {
        self.decoder.decompress(input, output, expected)
    }
}

/// Create a decoder only after admission, without constructing the native
/// encoder state carried by the upstream bidirectional codec objects.
pub(crate) fn create_admitted_decoder(
    codec: CodecType,
    options: &CodecOptions,
    policy: Option<&crate::resource::ReaderResourcePolicy>,
) -> Result<Option<Box<dyn Codec>>> {
    let Some(policy) = policy else {
        return create_codec(codec, options);
    };
    crate::resource::validate_thread_owner(Some(policy))?;
    let _ = policy; // non-codec feature builds retain typed unsupported handling
    match codec {
        CodecType::UNCOMPRESSED => Ok(None),
        #[cfg(any(feature = "zstd", test))]
        CodecType::ZSTD(_) => {
            policy.reserve(
                std::mem::size_of::<admitted_zstd::StaticDecoder>(),
                "zstd decoder owner",
            )?;
            Ok(Some(Box::new(admitted_zstd::StaticDecoder::try_new(
                policy.clone(),
            )?)))
        }
        #[cfg(any(feature = "snap", test))]
        CodecType::SNAPPY => {
            policy.reserve(
                std::mem::size_of::<AdmittedSnappyDecoder>(),
                "snappy decoder owner",
            )?;
            Ok(Some(Box::new(AdmittedSnappyDecoder {
                policy: policy.clone(),
            })))
        }
        // These profiles remain explicitly unavailable until their private
        // scratch allocations have corresponding preallocation proofs.
        _ => Err(crate::resource::ResourceExhausted {
            kind: "unsupported bounded codec profile",
            requested: 1,
            limit: 0,
        }
        .into()),
    }
}

#[cfg(any(feature = "snap", test))]
struct AdmittedSnappyDecoder {
    policy: crate::resource::ReaderResourcePolicy,
}
#[cfg(any(feature = "snap", test))]
impl Codec for AdmittedSnappyDecoder {
    fn compress(&mut self, _input: &[u8], _output: &mut Vec<u8>) -> Result<()> {
        Err(crate::resource::ResourceExhausted {
            kind: "decoder-only codec",
            requested: 1,
            limit: 0,
        }
        .into())
    }
    fn decompress(
        &mut self,
        input: &[u8],
        output: &mut Vec<u8>,
        expected: Option<usize>,
    ) -> Result<usize> {
        crate::resource::validate_thread_owner(Some(&self.policy))?;
        let _scope = crate::resource::enter(Some(self.policy.clone()));
        let expected = expected.ok_or(crate::resource::ResourceExhausted {
            kind: "missing decoded codec bound",
            requested: 1,
            limit: 0,
        })?;
        crate::resource::ReaderResourcePolicy::check(
            input.len(),
            self.policy.limits().page_bytes,
            "snappy encoded bytes",
        )?;
        crate::resource::ReaderResourcePolicy::check(
            expected,
            self.policy.limits().page_bytes,
            "snappy decoded bytes",
        )?;
        let declared = snap::raw::decompress_len(input)
            .map_err(|error| admitted_codec_error(&self.policy, error))?;
        crate::resource::ReaderResourcePolicy::check(declared, expected, "snappy decoded bytes")?;
        let start = output.len();
        crate::resource::reserve_vec(output, expected, "snappy decoded output")?;
        output.resize(start + expected, 0);
        // snap 1.1 Decoder is zero-sized and decompress writes only into the
        // provided slice; it neither creates an Encoder nor allocates scratch.
        let written = snap::raw::Decoder::new()
            .decompress(input, &mut output[start..])
            .map_err(|error| admitted_codec_error(&self.policy, error))?;
        output.truncate(start + written);
        Ok(written)
    }
}

#[cfg(any(feature = "zstd", test))]
mod admitted_zstd {
    use super::{Codec, CodecMessage, Result, ZstdLevel, admitted_codec_error};
    use crate::resource::{ReaderResourcePolicy, ResourceExhausted};
    use zstd::zstd_safe::{self, zstd_sys};

    /// Owns a native static DCtx in its fixed aligned workspace. No native
    /// pointer escapes: each exclusive call derives it from the live Vec.
    #[repr(C, align(8))]
    #[derive(Clone, Copy)]
    struct WorkspaceWord(u64);

    /// Lazy bidirectional context: reads do not allocate an encoder workspace.
    pub(super) struct StaticCodec {
        encoder: Option<StaticEncoder>,
        decoder: Option<StaticDecoder>,
        level: ZstdLevel,
        policy: ReaderResourcePolicy,
    }
    impl StaticCodec {
        pub(super) fn new(level: ZstdLevel, policy: ReaderResourcePolicy) -> Self {
            Self {
                encoder: None,
                decoder: None,
                level,
                policy,
            }
        }
    }
    impl Codec for StaticCodec {
        fn compress(&mut self, input: &[u8], output: &mut Vec<u8>) -> Result<()> {
            crate::resource::validate_thread_owner(Some(&self.policy))?;
            ReaderResourcePolicy::check(
                input.len(),
                self.policy.limits().page_bytes,
                "zstd input bytes",
            )?;
            if self.encoder.is_none() {
                self.encoder = Some(StaticEncoder::try_new(self.level, self.policy.clone())?);
            }
            self.encoder.as_mut().unwrap().compress(input, output)
        }
        fn decompress(
            &mut self,
            input: &[u8],
            output: &mut Vec<u8>,
            expected: Option<usize>,
        ) -> Result<usize> {
            crate::resource::validate_thread_owner(Some(&self.policy))?;
            if self.decoder.is_none() {
                self.decoder = Some(StaticDecoder::try_new(self.policy.clone())?);
            }
            self.decoder
                .as_mut()
                .unwrap()
                .decompress(input, output, expected)
        }
    }

    struct StaticEncoder {
        workspace: Vec<WorkspaceWord>,
        level: ZstdLevel,
        policy: ReaderResourcePolicy,
    }
    impl StaticEncoder {
        fn try_new(level: ZstdLevel, policy: ReaderResourcePolicy) -> Result<Self> {
            // SAFETY: pure size query from the compiled zstd 1.5.7. Its source
            // takes the maximum over all source-size tiers and all levels up
            // to this level; this is the single-shot CCtx bound for any input.
            let required = unsafe { zstd_sys::ZSTD_estimateCCtxSize(level.0) };
            // SAFETY: native error-code inspection reads no caller memory.
            if unsafe { zstd_sys::ZSTD_isError(required) } != 0 {
                return Err(ResourceExhausted {
                    kind: "zstd encoder workspace profile",
                    requested: level.0 as usize,
                    limit: 0,
                }
                .into());
            }
            let words = required
                .checked_add(7)
                .map(|n| n / 8)
                .ok_or(ResourceExhausted {
                    kind: "zstd encoder workspace",
                    requested: usize::MAX,
                    limit: policy.limits().codec_bytes,
                })?;
            let bytes = words.checked_mul(8).ok_or(ResourceExhausted {
                kind: "zstd encoder workspace",
                requested: usize::MAX,
                limit: policy.limits().codec_bytes,
            })?;
            ReaderResourcePolicy::check(
                bytes,
                policy.limits().codec_bytes,
                "zstd encoder workspace",
            )?;
            policy.reserve(bytes, "zstd encoder workspace")?;
            let mut workspace = Vec::<WorkspaceWord>::new();
            workspace
                .try_reserve_exact(words)
                .map_err(|_| ResourceExhausted {
                    kind: "native allocation failed",
                    requested: bytes,
                    limit: bytes,
                })?;
            workspace.resize(words, WorkspaceWord(0));
            // SAFETY: the initialized allocation has the admitted size and
            // explicit 8-byte alignment. It never resizes after initialization;
            // moving its Vec does not move the native self-relative pointers.
            // Static CCtx neither owns malloc backing nor needs a native free.
            let context =
                unsafe { zstd_sys::ZSTD_initStaticCCtx(workspace.as_mut_ptr().cast(), bytes) };
            if context.is_null() {
                return Err(ResourceExhausted {
                    kind: "zstd encoder initialization",
                    requested: required,
                    limit: bytes,
                }
                .into());
            }
            debug_assert_eq!(context.cast::<WorkspaceWord>(), workspace.as_mut_ptr());
            Ok(Self {
                workspace,
                level,
                policy,
            })
        }

        fn compress(&mut self, input: &[u8], output: &mut Vec<u8>) -> Result<()> {
            crate::resource::validate_thread_owner(Some(&self.policy))?;
            let _scope = crate::resource::enter(Some(self.policy.clone()));
            ReaderResourcePolicy::check(
                input.len(),
                self.policy.limits().page_bytes,
                "zstd input bytes",
            )?;
            let bound = zstd_safe::compress_bound(input.len());
            let start = output.len();
            crate::resource::reserve_vec(output, bound, "zstd encoded output")?;
            output.resize(start + bound, 0);
            // SAFETY: exclusive initialized static CCtx; fixed workspace and
            // disjoint live slices covering exactly the supplied lengths.
            // Reinitialize the fixed workspace for every independent page.
            // initStaticCCtx zeroes the context before installing only pointers
            // into this workspace. No pointer from an earlier caller survives.
            // The prior single-shot operation installed no owned dictionaries,
            // workers or dynamic backing requiring a destructor. This is not
            // a streaming encoder; static exhaustion never reallocates.
            let context = unsafe {
                zstd_sys::ZSTD_initStaticCCtx(
                    self.workspace.as_mut_ptr().cast(),
                    self.workspace.len() * 8,
                )
            };
            if context.is_null() {
                output.truncate(start);
                return Err(ResourceExhausted {
                    kind: "zstd encoder initialization",
                    requested: self.workspace.len() * 8,
                    limit: 0,
                }
                .into());
            }
            // SAFETY: the context and disjoint input/output slices satisfy the
            // exclusive fixed-workspace contract described immediately above.
            let code = unsafe {
                zstd_sys::ZSTD_compressCCtx(
                    context,
                    output[start..].as_mut_ptr().cast(),
                    bound,
                    input.as_ptr().cast(),
                    input.len(),
                    self.level.0,
                )
            };
            // SAFETY: native error-code inspection reads no caller memory.
            if unsafe { zstd_sys::ZSTD_isError(code) } != 0 {
                output.truncate(start);
                // SAFETY: code is the result of the native operation above.
                return match unsafe { zstd_sys::ZSTD_getErrorCode(code) } {
                    zstd_sys::ZSTD_ErrorCode::ZSTD_error_memory_allocation => {
                        Err(ResourceExhausted {
                            kind: "zstd encoder workspace",
                            requested: self.workspace.len().saturating_mul(8).saturating_add(1),
                            limit: self.workspace.len() * 8,
                        }
                        .into())
                    }
                    zstd_sys::ZSTD_ErrorCode::ZSTD_error_dstSize_tooSmall => {
                        Err(ResourceExhausted {
                            kind: "zstd encoded bytes",
                            requested: bound.saturating_add(1),
                            limit: bound,
                        }
                        .into())
                    }
                    _ => Err(admitted_codec_error(
                        &self.policy,
                        CodecMessage("ZSTD compression failed"),
                    )),
                };
            }
            output.truncate(start + code);
            Ok(())
        }
    }

    pub(super) struct StaticDecoder {
        workspace: Vec<WorkspaceWord>,
        policy: ReaderResourcePolicy,
    }

    impl StaticDecoder {
        pub(super) fn try_new(policy: ReaderResourcePolicy) -> Result<Self> {
            // SAFETY: no pointers or mutable state; this native function returns
            // the exact sizeof(ZSTD_DCtx) of the compiled zstd 1.5.7 library.
            let required = unsafe { zstd_sys::ZSTD_estimateDCtxSize() };
            let words = required
                .checked_add(7)
                .map(|n| n / 8)
                .ok_or(ResourceExhausted {
                    kind: "zstd static workspace",
                    requested: usize::MAX,
                    limit: policy.limits().codec_bytes,
                })?;
            let bytes = words.checked_mul(8).ok_or(ResourceExhausted {
                kind: "zstd static workspace",
                requested: usize::MAX,
                limit: policy.limits().codec_bytes,
            })?;
            ReaderResourcePolicy::check(
                bytes,
                policy.limits().codec_bytes,
                "zstd static workspace",
            )?;
            policy.reserve(bytes, "zstd static workspace")?;
            let mut workspace = Vec::<WorkspaceWord>::new();
            workspace
                .try_reserve_exact(words)
                .map_err(|_| ResourceExhausted {
                    kind: "native allocation failed",
                    requested: bytes,
                    limit: bytes,
                })?;
            workspace.resize(words, WorkspaceWord(0));
            // SAFETY: repr(align(8)) WorkspaceWord is 8-byte aligned on every
            // supported platform, initialized, and covers the
            // exact admitted native context size. It is never resized after
            // this call; moving the owning Vec does not move its allocation.
            // ZSTD static contexts never malloc/realloc and have no free call.
            let context =
                unsafe { zstd_sys::ZSTD_initStaticDCtx(workspace.as_mut_ptr().cast(), bytes) };
            if context.is_null() {
                return Err(ResourceExhausted {
                    kind: "zstd static initialization",
                    requested: required,
                    limit: bytes,
                }
                .into());
            }
            debug_assert_eq!(context.cast::<WorkspaceWord>(), workspace.as_mut_ptr());
            Ok(Self { workspace, policy })
        }
    }

    impl Codec for StaticDecoder {
        fn compress(&mut self, _input: &[u8], _output: &mut Vec<u8>) -> Result<()> {
            Err(ResourceExhausted {
                kind: "decoder-only codec",
                requested: 1,
                limit: 0,
            }
            .into())
        }

        fn decompress(
            &mut self,
            input: &[u8],
            output: &mut Vec<u8>,
            expected: Option<usize>,
        ) -> Result<usize> {
            crate::resource::validate_thread_owner(Some(&self.policy))?;
            let _scope = crate::resource::enter(Some(self.policy.clone()));
            let expected = expected.ok_or(ResourceExhausted {
                kind: "missing decoded codec bound",
                requested: 1,
                limit: 0,
            })?;
            ReaderResourcePolicy::check(
                input.len(),
                self.policy.limits().page_bytes,
                "zstd encoded bytes",
            )?;
            ReaderResourcePolicy::check(
                expected,
                self.policy.limits().page_bytes,
                "zstd decoded bytes",
            )?;
            // Static DCtx deliberately excludes legacy frames. Check every
            // concatenated native frame before invoking the decoder; standard
            // and skippable frames preserve native concatenation semantics.
            let mut frames = input;
            while !frames.is_empty() {
                let magic = frames
                    .get(..4)
                    .map(|s| u32::from_le_bytes(s.try_into().unwrap()));
                if !matches!(magic, Some(0xfd2fb528) | Some(0x184d2a50..=0x184d2a5f)) {
                    return Err(ResourceExhausted {
                        kind: "unsupported bounded zstd frame",
                        requested: 1,
                        limit: 0,
                    }
                    .into());
                }
                let length = zstd_safe::find_frame_compressed_size(frames).map_err(|_| {
                    admitted_codec_error(&self.policy, CodecMessage("Invalid ZSTD frame"))
                })?;
                if length == 0 || length > frames.len() {
                    return Err(admitted_codec_error(
                        &self.policy,
                        CodecMessage("Invalid ZSTD frame length"),
                    ));
                }
                frames = &frames[length..];
            }
            let start = output.len();
            crate::resource::reserve_vec(output, expected, "zstd decoded output")?;
            output.resize(start + expected, 0);
            // SAFETY: self exclusively owns the initialized static DCtx; its
            // allocation never grows and outlives this call. Input and output
            // are disjoint Rust borrows. Output capacity is the admitted slice
            // length, not Vec capacity. Native static DCtx cannot allocate any
            // extra context/window/scratch backing and fails if insufficient.
            // zstd 1.5.7 decompressMultiFrame (zstd_decompress.c:1133-1141)
            // calls decompressBegin_usingDict(NULL,0) before checkContinuity;
            // decompressBegin (:1560-1573) resets every prior output/dictionary
            // pointer. Thus each earlier output may drop before context reuse.
            let code = unsafe {
                zstd_sys::ZSTD_decompressDCtx(
                    self.workspace.as_mut_ptr().cast(),
                    output[start..].as_mut_ptr().cast(),
                    expected,
                    input.as_ptr().cast(),
                    input.len(),
                )
            };
            // SAFETY: error-code inspection reads no caller memory.
            if unsafe { zstd_sys::ZSTD_isError(code) } != 0 {
                // SAFETY: code came from the native function above.
                let error = unsafe { zstd_sys::ZSTD_getErrorCode(code) };
                return match error {
                    zstd_sys::ZSTD_ErrorCode::ZSTD_error_memory_allocation => {
                        Err(ResourceExhausted {
                            kind: "zstd static workspace",
                            requested: self.workspace.len().saturating_mul(8).saturating_add(1),
                            limit: self.workspace.len() * 8,
                        }
                        .into())
                    }
                    zstd_sys::ZSTD_ErrorCode::ZSTD_error_dstSize_tooSmall => {
                        Err(ResourceExhausted {
                            kind: "zstd decoded bytes",
                            requested: expected.saturating_add(1),
                            limit: expected,
                        }
                        .into())
                    }
                    _ => Err(admitted_codec_error(
                        &self.policy,
                        CodecMessage("Invalid ZSTD compressed page"),
                    )),
                };
            }
            output.truncate(start + code);
            Ok(code)
        }
    }
}

/// The guarded streaming path never lets Read::read_to_end grow an output Vec
/// beyond the declared decoded length. Excess output is detected in one stack
/// byte, before any additional output allocation. Codec-private scratch is a
/// separate allocation boundary and is not certified by this output guard.
#[cfg(any(feature = "flate2", feature = "brotli", feature = "lz4", test))]
fn read_decompressed<R: std::io::Read>(
    mut reader: R,
    output: &mut Vec<u8>,
    expected: Option<usize>,
) -> Result<usize> {
    let Some(policy) = crate::resource::current() else {
        return Ok(reader.read_to_end(output)?);
    };
    let expected = expected.ok_or(crate::resource::ResourceExhausted {
        kind: "missing decoded codec bound",
        requested: 1,
        limit: 0,
    })?;
    crate::resource::ReaderResourcePolicy::check(
        expected,
        policy.limits().page_bytes,
        "codec decoded bytes",
    )?;
    let start = output.len();
    crate::resource::reserve_vec(output, expected, "codec decoded output")?;
    output.resize(start + expected, 0);
    let mut read = 0;
    while read < expected {
        let count = reader.read(&mut output[start + read..])?;
        if count == 0 {
            break;
        }
        read += count;
    }
    if read == expected {
        let mut overflow = [0_u8; 1];
        if reader.read(&mut overflow)? != 0 {
            return Err(crate::resource::ResourceExhausted {
                kind: "codec decoded bytes",
                requested: expected.saturating_add(1),
                limit: expected,
            }
            .into());
        }
    }
    output.truncate(start + read);
    Ok(read)
}

#[cfg(any(feature = "snap", test))]
mod snappy_codec {
    use snap::raw::{Decoder, Encoder, decompress_len, max_compress_len};

    use crate::compression::Codec;
    use crate::errors::Result;

    /// Codec for Snappy compression format.
    pub struct SnappyCodec {
        decoder: Decoder,
        encoder: Encoder,
    }

    impl SnappyCodec {
        /// Creates new Snappy compression codec.
        pub(crate) fn new() -> Self {
            Self {
                decoder: Decoder::new(),
                encoder: Encoder::new(),
            }
        }
    }

    impl Codec for SnappyCodec {
        fn decompress(
            &mut self,
            input_buf: &[u8],
            output_buf: &mut Vec<u8>,
            uncompress_size: Option<usize>,
        ) -> Result<usize> {
            let len = match uncompress_size {
                Some(size) => size,
                None => decompress_len(input_buf)?,
            };
            let offset = output_buf.len();
            crate::resource::reserve_vec(output_buf, len, "snappy decoded output")?;
            output_buf.resize(offset + len, 0);
            self.decoder
                .decompress(input_buf, &mut output_buf[offset..])
                .map_err(|e| e.into())
        }

        fn compress(&mut self, input_buf: &[u8], output_buf: &mut Vec<u8>) -> Result<()> {
            let output_buf_len = output_buf.len();
            let required_len = max_compress_len(input_buf.len());
            output_buf.resize(output_buf_len + required_len, 0);
            let n = self
                .encoder
                .compress(input_buf, &mut output_buf[output_buf_len..])?;
            output_buf.truncate(output_buf_len + n);
            Ok(())
        }
    }
}
