#[cfg(any(feature = "lz4", test))]
mod lz4_hadoop_codec {
    use crate::compression::Codec;
    use crate::compression::lz4_codec::LZ4Codec;
    use crate::compression::lz4_raw_codec::LZ4RawCodec;
    use crate::errors::{ParquetError, Result};
    use std::io;

    /// Size of u32 type.
    const SIZE_U32: usize = std::mem::size_of::<u32>();

    /// Length of the LZ4_HADOOP prefix.
    const PREFIX_LEN: usize = SIZE_U32 * 2;

    /// Codec for LZ4 Hadoop compression algorithm.
    pub struct LZ4HadoopCodec {
        /// Whether or not to fallback to other LZ4 implementations on error.
        /// Fallback is done to be backward compatible with older versions of this
        /// library and older versions parquet-cpp.
        backward_compatible_lz4: bool,
    }

    impl LZ4HadoopCodec {
        /// Creates new LZ4 Hadoop compression codec.
        pub(crate) fn new(backward_compatible_lz4: bool) -> Self {
            Self {
                backward_compatible_lz4,
            }
        }
    }

    /// Try to decompress the buffer as if it was compressed with the Hadoop Lz4Codec.
    /// Adapted from pola-rs [compression.rs:try_decompress_hadoop](https://pola-rs.github.io/polars/src/parquet2/compression.rs.html#225)
    /// Translated from the apache arrow c++ function [TryDecompressHadoop](https://github.com/apache/arrow/blob/bf18e6e4b5bb6180706b1ba0d597a65a4ce5ca48/cpp/src/arrow/util/compression_lz4.cc#L474).
    /// Returns error if decompression failed.
    fn try_decompress_hadoop(input_buf: &[u8], output_buf: &mut [u8]) -> io::Result<usize> {
        // Parquet files written with the Hadoop Lz4Codec use their own framing.
        // The input buffer can contain an arbitrary number of "frames", each
        // with the following structure:
        // - bytes 0..3: big-endian uint32_t representing the frame decompressed size
        // - bytes 4..7: big-endian uint32_t representing the frame compressed size
        // - bytes 8...: frame compressed data
        //
        // The Hadoop Lz4Codec source code can be found here:
        // https://github.com/apache/hadoop/blob/trunk/hadoop-mapreduce-project/hadoop-mapreduce-client/hadoop-mapreduce-client-nativetask/src/main/native/src/codec/Lz4Codec.cc
        let mut input_len = input_buf.len();
        let mut input = input_buf;
        let mut read_bytes = 0;
        let mut output_len = output_buf.len();
        let mut output: &mut [u8] = output_buf;
        while input_len >= PREFIX_LEN {
            let mut bytes = [0; SIZE_U32];
            bytes.copy_from_slice(&input[0..4]);
            let expected_decompressed_size = u32::from_be_bytes(bytes);
            let mut bytes = [0; SIZE_U32];
            bytes.copy_from_slice(&input[4..8]);
            let expected_compressed_size = u32::from_be_bytes(bytes);
            input = &input[PREFIX_LEN..];
            input_len -= PREFIX_LEN;

            if input_len < expected_compressed_size as usize {
                return Err(io::Error::other("Not enough bytes for Hadoop frame"));
            }

            if output_len < expected_decompressed_size as usize {
                return Err(io::Error::other(
                    "Not enough bytes to hold advertised output",
                ));
            }
            let decompressed_size =
                lz4_flex::decompress_into(&input[..expected_compressed_size as usize], output)
                    .map_err(|e| ParquetError::External(Box::new(e)))?;
            if decompressed_size != expected_decompressed_size as usize {
                return Err(io::Error::other("Unexpected decompressed size"));
            }
            input_len -= expected_compressed_size as usize;
            output_len -= expected_decompressed_size as usize;
            read_bytes += expected_decompressed_size as usize;
            if input_len > expected_compressed_size as usize {
                input = &input[expected_compressed_size as usize..];
                output = &mut output[expected_decompressed_size as usize..];
            } else {
                break;
            }
        }
        if input_len == 0 {
            Ok(read_bytes)
        } else {
            Err(io::Error::other("Not all input are consumed"))
        }
    }

    impl Codec for LZ4HadoopCodec {
        fn decompress(
            &mut self,
            input_buf: &[u8],
            output_buf: &mut Vec<u8>,
            uncompress_size: Option<usize>,
        ) -> Result<usize> {
            let output_len = output_buf.len();
            let required_len = match uncompress_size {
                Some(n) => n,
                None => {
                    return Err(ParquetError::General(
                        "LZ4HadoopCodec unsupported without uncompress_size".into(),
                    ));
                }
            };
            crate::resource::reserve_vec(output_buf, required_len, "lz4 hadoop decoded output")?;
            output_buf.resize(output_len + required_len, 0);
            match try_decompress_hadoop(input_buf, &mut output_buf[output_len..]) {
                Ok(n) => {
                    if n != required_len {
                        return Err(ParquetError::General(
                            "LZ4HadoopCodec uncompress_size is not the expected one".into(),
                        ));
                    }
                    Ok(n)
                }
                Err(e) if !self.backward_compatible_lz4 => Err(e.into()),
                // Fallback done to be backward compatible with older versions of this
                // library and older versions of parquet-cpp.
                Err(_) => {
                    // Truncate any inserted element before tryingg next algorithm.
                    output_buf.truncate(output_len);
                    match LZ4Codec::new().decompress(input_buf, output_buf, uncompress_size) {
                        Ok(n) => Ok(n),
                        Err(error @ ParquetError::ResourceExhausted(_)) => Err(error),
                        Err(_) => {
                            // Truncate any inserted element before tryingg next algorithm.
                            output_buf.truncate(output_len);
                            LZ4RawCodec::new().decompress(input_buf, output_buf, uncompress_size)
                        }
                    }
                }
            }
        }

        fn compress(&mut self, input_buf: &[u8], output_buf: &mut Vec<u8>) -> Result<()> {
            // Allocate memory to store the LZ4_HADOOP prefix.
            let offset = output_buf.len();
            output_buf.resize(offset + PREFIX_LEN, 0);

            // Append LZ4_RAW compressed bytes after prefix.
            LZ4RawCodec::new().compress(input_buf, output_buf)?;

            // Prepend decompressed size and compressed size in big endian to be compatible
            // with LZ4_HADOOP.
            let output_buf = &mut output_buf[offset..];
            let compressed_size = output_buf.len() - PREFIX_LEN;
            let compressed_size = compressed_size as u32;
            let uncompressed_size = input_buf.len() as u32;
            output_buf[..SIZE_U32].copy_from_slice(&uncompressed_size.to_be_bytes());
            output_buf[SIZE_U32..PREFIX_LEN].copy_from_slice(&compressed_size.to_be_bytes());

            Ok(())
        }
    }
}
#[cfg(any(feature = "lz4", test))]
pub use lz4_hadoop_codec::*;

#[cfg(test)]
mod tests {
    use super::*;

    use crate::util::test_common::rand_gen::random_bytes;

    fn test_roundtrip(c: CodecType, data: &[u8], uncompress_size: Option<usize>) {
        let codec_options = CodecOptionsBuilder::default()
            .set_backward_compatible_lz4(false)
            .build();
        let mut c1 = create_codec(c, &codec_options).unwrap().unwrap();
        let mut c2 = create_codec(c, &codec_options).unwrap().unwrap();

        // Compress with c1
        let mut compressed = Vec::new();
        let mut decompressed = Vec::new();
        c1.compress(data, &mut compressed)
            .expect("Error when compressing");

        // Decompress with c2
        let decompressed_size = c2
            .decompress(compressed.as_slice(), &mut decompressed, uncompress_size)
            .expect("Error when decompressing");
        assert_eq!(data.len(), decompressed_size);
        assert_eq!(data, decompressed.as_slice());

        decompressed.clear();
        compressed.clear();

        // Compress with c2
        c2.compress(data, &mut compressed)
            .expect("Error when compressing");

        // Decompress with c1
        let decompressed_size = c1
            .decompress(compressed.as_slice(), &mut decompressed, uncompress_size)
            .expect("Error when decompressing");
        assert_eq!(data.len(), decompressed_size);
        assert_eq!(data, decompressed.as_slice());

        decompressed.clear();
        compressed.clear();

        // Test does not trample existing data in output buffers
        let prefix = &[0xDE, 0xAD, 0xBE, 0xEF];
        decompressed.extend_from_slice(prefix);
        compressed.extend_from_slice(prefix);

        c2.compress(data, &mut compressed)
            .expect("Error when compressing");

        assert_eq!(&compressed[..4], prefix);

        let decompressed_size = c2
            .decompress(&compressed[4..], &mut decompressed, uncompress_size)
            .expect("Error when decompressing");

        assert_eq!(data.len(), decompressed_size);
        assert_eq!(data, &decompressed[4..]);
        assert_eq!(&decompressed[..4], prefix);
    }

    fn test_codec_with_size(c: CodecType) {
        let sizes = vec![100, 10000, 100000];
        for size in sizes {
            let data = random_bytes(size);
            test_roundtrip(c, &data, Some(data.len()));
        }
    }

    fn test_codec_without_size(c: CodecType) {
        let sizes = vec![100, 10000, 100000];
        for size in sizes {
            let data = random_bytes(size);
            test_roundtrip(c, &data, None);
        }
    }

    #[test]
    fn test_codec_snappy() {
        test_codec_with_size(CodecType::SNAPPY);
        test_codec_without_size(CodecType::SNAPPY);
    }

    #[test]
    fn test_codec_gzip() {
        for level in GzipLevel::MINIMUM_LEVEL..=GzipLevel::MAXIMUM_LEVEL {
            let level = GzipLevel::try_new(level).unwrap();
            test_codec_with_size(CodecType::GZIP(level));
            test_codec_without_size(CodecType::GZIP(level));
        }
    }

    #[test]
    fn test_codec_brotli() {
        for level in BrotliLevel::MINIMUM_LEVEL..=BrotliLevel::MAXIMUM_LEVEL {
            let level = BrotliLevel::try_new(level).unwrap();
            test_codec_with_size(CodecType::BROTLI(level));
            test_codec_without_size(CodecType::BROTLI(level));
        }
    }

    #[test]
    fn test_codec_lz4() {
        test_codec_with_size(CodecType::LZ4);
    }

    #[test]
    fn test_codec_zstd() {
        for level in ZstdLevel::MINIMUM_LEVEL..=ZstdLevel::MAXIMUM_LEVEL {
            let level = ZstdLevel::try_new(level).unwrap();
            test_codec_with_size(CodecType::ZSTD(level));
            test_codec_without_size(CodecType::ZSTD(level));
        }
    }

    #[test]
    fn test_codec_lz4_raw() {
        test_codec_with_size(CodecType::LZ4_RAW);
    }
}

#[cfg(test)]
mod resource_codec_tests {
    use super::*;
    use crate::resource::{ResourceExhausted, tests::policy};
    use std::sync::atomic::Ordering;

    fn writer_policy(
        deny: &'static str,
    ) -> (
        crate::resource::ReaderResourcePolicy,
        std::sync::Arc<crate::resource::tests::Admission>,
    ) {
        let (original, admission) = policy(deny);
        let mut limits = original.limits();
        limits.codec_bytes = 16 * 1024 * 1024;
        let policy =
            crate::resource::ReaderResourcePolicy::try_new(admission.clone(), limits).unwrap();
        (policy, admission)
    }

    #[test]
    fn resource_native_encoders_roundtrip_and_reuse_original_static_scratch() {
        for codec in [CodecType::SNAPPY, CodecType::ZSTD(ZstdLevel::default())] {
            let (policy, admission) = writer_policy("");
            let guard = policy.enter_thread();
            let mut encoder = create_codec(codec, &CodecOptions::default())
                .unwrap()
                .unwrap();
            for size in [0, 1, 4096, 8192, 17] {
                let input: Vec<u8> = (0..size).map(|i| (i * 31) as u8).collect();
                let mut encoded = vec![0x42];
                encoder.compress(&input, &mut encoded).unwrap();
                assert_eq!(encoded[0], 0x42);
                let mut output = vec![0x24];
                encoder
                    .decompress(&encoded[1..], &mut output, Some(size))
                    .unwrap();
                assert_eq!(output[0], 0x24);
                assert_eq!(&output[1..], input);
                // These allocations are dropped before reusing the contexts.
            }
            let requests = admission.requests.lock().unwrap();
            let kind = if matches!(codec, CodecType::SNAPPY) {
                "snappy encoder scratch"
            } else {
                "zstd encoder workspace"
            };
            assert_eq!(requests.iter().filter(|r| r.kind == kind).count(), 1);
            drop(requests);
            drop(guard);
            drop(policy);
            assert!(admission.live.load(Ordering::Acquire) > 0);
            drop(encoder);
            assert_eq!(admission.live.load(Ordering::Acquire), 0);
        }
    }

    #[test]
    fn resource_native_encoder_denials_precede_output_growth_and_context_work() {
        for (codec, kind) in [
            (CodecType::SNAPPY, "snappy encoder scratch"),
            (CodecType::SNAPPY, "snappy encoded output"),
            (
                CodecType::ZSTD(ZstdLevel::default()),
                "zstd encoder workspace",
            ),
            (CodecType::ZSTD(ZstdLevel::default()), "zstd encoded output"),
        ] {
            let (policy, admission) = writer_policy(kind);
            let guard = policy.enter_thread();
            let mut codec = create_codec(codec, &CodecOptions::default())
                .unwrap()
                .unwrap();
            let mut output = Vec::new();
            assert!(matches!(codec.compress(b"input", &mut output),
                Err(ParquetError::ResourceExhausted(error)) if error.kind == kind));
            assert_eq!(output.capacity(), 0);
            assert_eq!(
                admission.requests.lock().unwrap().last().unwrap().kind,
                kind
            );
            drop(codec);
            drop(guard);
            drop(policy);
            assert_eq!(admission.live.load(Ordering::Acquire), 0);
        }
    }

    #[test]
    fn resource_codec_read_path_does_not_create_encoder_scratch() {
        let input = b"codec read";
        let encoded = zstd::bulk::compress(input, 1).unwrap();
        let (policy, admission) = writer_policy("zstd encoder workspace");
        let guard = policy.enter_thread();
        let mut codec = create_codec(
            CodecType::ZSTD(ZstdLevel::default()),
            &CodecOptions::default(),
        )
        .unwrap()
        .unwrap();
        let mut output = Vec::new();
        codec
            .decompress(&encoded, &mut output, Some(input.len()))
            .unwrap();
        assert_eq!(output, input);
        assert!(
            !admission
                .requests
                .lock()
                .unwrap()
                .iter()
                .any(|r| r.kind == "zstd encoder workspace")
        );
        drop(guard);
    }

    #[test]
    fn resource_malformed_codec_diagnostic_is_admitted_and_keeps_original_owner() {
        for (codec, input) in [
            (CodecType::SNAPPY, &[0xff, 0xff, 0xff, 0xff, 0xff, 0xff][..]),
            (
                CodecType::ZSTD(ZstdLevel::default()),
                &[0x28, 0xb5, 0x2f, 0xfd][..],
            ),
        ] {
            for deny in ["", "codec diagnostic"] {
                let (policy, admission) = writer_policy(deny);
                let guard = policy.enter_thread();
                let mut codec = create_codec(codec, &CodecOptions::default())
                    .unwrap()
                    .unwrap();
                let mut output = Vec::new();
                let error = codec.decompress(input, &mut output, Some(16)).unwrap_err();
                assert_eq!(output.capacity(), 0);
                if deny.is_empty() {
                    assert!(matches!(error, ParquetError::External(_)));
                } else {
                    assert!(matches!(error, ParquetError::ResourceExhausted(e) if e.kind == deny));
                }
                drop(codec);
                drop(guard);
                drop(policy);
                if deny.is_empty() {
                    assert!(admission.live.load(Ordering::Acquire) > 0);
                } else {
                    assert_eq!(admission.live.load(Ordering::Acquire), 0);
                }
                drop(error);
                assert_eq!(admission.live.load(Ordering::Acquire), 0);
            }
        }
    }

    #[test]
    fn resource_codec_rejects_foreign_worker_before_allocating_context() {
        let (original, admission) = writer_policy("");
        let original_guard = original.enter_thread();
        let mut codec = create_codec(
            CodecType::ZSTD(ZstdLevel::default()),
            &CodecOptions::default(),
        )
        .unwrap()
        .unwrap();
        drop(original_guard);
        let (foreign, _) = writer_policy("");
        let _foreign_guard = foreign.enter_thread();
        let count = admission.requests.lock().unwrap().len();
        let mut output = Vec::new();
        assert!(
            matches!(codec.compress(b"input", &mut output), Err(ParquetError::ResourceExhausted(e))
            if e.kind == "reader belongs to another resource scope")
        );
        assert_eq!(admission.requests.lock().unwrap().len(), count);
        assert_eq!(output.capacity(), 0);
    }

    #[test]
    fn resource_zstd_static_workspace_denial_precedes_context_initialization() {
        let (policy, admission) = policy("zstd static workspace");
        let result = create_admitted_decoder(
            CodecType::ZSTD(Default::default()),
            &CodecOptions::default(),
            Some(&policy),
        );
        assert!(matches!(
            result,
            Err(ParquetError::ResourceExhausted(ResourceExhausted {
                kind: "zstd static workspace",
                ..
            }))
        ));
        let requests = admission.requests.lock().unwrap();
        assert_eq!(requests.last().unwrap().kind, "zstd static workspace");
        drop(requests);
        drop(policy);
        assert_eq!(admission.live.load(Ordering::Acquire), 0);
    }

    #[test]
    fn resource_zstd_static_native_decode_reuses_fixed_workspace_and_rejects_expansion() {
        let data = vec![b'a'; 4096];
        let compressed = zstd::bulk::compress(&data, 3).unwrap();
        let (policy, admission) = policy("");
        let mut decoder = create_admitted_decoder(
            CodecType::ZSTD(Default::default()),
            &CodecOptions::default(),
            Some(&policy),
        )
        .unwrap()
        .unwrap();
        for _ in 0..2 {
            let mut output = Vec::new();
            assert_eq!(
                decoder
                    .decompress(&compressed, &mut output, Some(data.len()))
                    .unwrap(),
                data.len()
            );
            assert_eq!(output, data);
        }
        assert_eq!(
            admission
                .requests
                .lock()
                .unwrap()
                .iter()
                .filter(|r| r.kind == "zstd static workspace")
                .count(),
            1
        );
        let mut output = Vec::new();
        let error = decoder
            .decompress(&compressed, &mut output, Some(128))
            .unwrap_err();
        assert!(matches!(
            error,
            ParquetError::ResourceExhausted(ResourceExhausted {
                kind: "zstd decoded bytes",
                requested: 129,
                limit: 128
            })
        ));
        assert_eq!(output.capacity(), 128);
        assert_eq!(output.len(), 128);
        drop(policy);
        assert!(admission.live.load(Ordering::Acquire) > 0);
        drop(decoder);
        assert_eq!(admission.live.load(Ordering::Acquire), 0);
    }

    #[test]
    fn resource_zstd_static_decoder_rejects_legacy_frame_profile() {
        let (policy, _) = policy("");
        let mut decoder = create_admitted_decoder(
            CodecType::ZSTD(Default::default()),
            &CodecOptions::default(),
            Some(&policy),
        )
        .unwrap()
        .unwrap();
        let error = decoder
            .decompress(&[0x27, 0xb5, 0x2f, 0xfd], &mut Vec::new(), Some(1))
            .unwrap_err();
        assert!(matches!(
            error,
            ParquetError::ResourceExhausted(ResourceExhausted {
                kind: "unsupported bounded zstd frame",
                ..
            })
        ));
    }

    #[test]
    fn resource_streaming_codec_output_rejects_before_capacity_growth() {
        let (policy, _) = policy("");
        let _scope = crate::resource::enter(Some(policy));
        let mut output = Vec::with_capacity(4);
        let error = read_decompressed(&b"expanded"[..], &mut output, Some(4)).unwrap_err();
        assert!(matches!(
            error,
            ParquetError::ResourceExhausted(ResourceExhausted {
                kind: "codec decoded bytes",
                requested: 5,
                limit: 4
            })
        ));
        assert_eq!(output.capacity(), 4);
        assert_eq!(output, b"expa");
    }
}
